INSERT INTO questions (id, quiz_id, sort_order, text, weight, source_label, source_url, source_date) VALUES
  (101, 101, 1, 'Czy obywatelski projekt ustawy o zmianie ustawy o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych (finansowanie in vitro) powinien zostać uchwalony?', 2, 'Sejm 10 kadencji, posiedzenie nr 1, głosowanie nr 40 – głosowanie nad całością projektu', 'https://api.sejm.gov.pl/sejm/term10/votings/1/40/pdf', '2023-11-29'),
  (102, 101, 2, 'Czy Sejm powinien przyjąć uchwałę w sprawie przywrócenia ładu prawnego oraz bezstronności i rzetelności mediów publicznych oraz Polskiej Agencji Prasowej?', 2, 'Sejm 10 kadencji, posiedzenie nr 1, głosowanie nr 122 – głosowanie nad całością projektu', 'https://api.sejm.gov.pl/sejm/term10/votings/1/122/pdf', '2023-12-19'),
  (103, 101, 3, 'Czy ustawa o szczególnych rozwiązaniach służących realizacji ustawy budżetowej na rok 2024 powinna zostać uchwalona?', 2, 'Sejm 10 kadencji, posiedzenie nr 1, głosowanie nr 140 – głosowanie nad całością projektu', 'https://api.sejm.gov.pl/sejm/term10/votings/1/140/pdf', '2023-12-21'),
  (104, 101, 4, 'Czy ustawa o zmianie ustawy – Prawo farmaceutyczne (tzw. pigułka „dzień po”) powinna zostać uchwalona?', 2, 'Sejm 10 kadencji, posiedzenie nr 6, głosowanie nr 14 – głosowanie nad całością projektu', 'https://api.sejm.gov.pl/sejm/term10/votings/6/14/pdf', '2024-02-22'),
  (105, 101, 5, 'Czy Sejm powinien przyjąć uchwałę w sprawie usunięcia skutków kryzysu konstytucyjnego lat 2015–2023 w kontekście działalności Trybunału Konstytucyjnego?', 2, 'Sejm 10 kadencji, posiedzenie nr 7, głosowanie nr 8 – głosowanie nad całością projektu', 'https://api.sejm.gov.pl/sejm/term10/votings/7/8/pdf', '2024-03-06'),
  (106, 101, 6, 'Czy ustawa o zmianie ustawy o mniejszościach narodowych i etnicznych oraz o języku regionalnym (język śląski) powinna zostać uchwalona?', 2, 'Sejm 10 kadencji, posiedzenie nr 10, głosowanie nr 13 – głosowanie nad całością projektu', 'https://api.sejm.gov.pl/sejm/term10/votings/10/13/pdf', '2024-04-26'),
  (107, 101, 7, 'Czy ustawa o zmianie ustawy – Kodeks karny (dekryminalizacja aborcji) powinna zostać uchwalona?', 2, 'Sejm 10 kadencji, posiedzenie nr 15, głosowanie nr 9 – głosowanie nad całością projektu', 'https://api.sejm.gov.pl/sejm/term10/votings/15/9/pdf', '2024-07-12'),
  (108, 101, 8, 'Czy ustawa o uchyleniu ustawy o Państwowej Komisji do spraw badania wpływów rosyjskich na bezpieczeństwo wewnętrzne Rzeczypospolitej Polskiej w latach 2007–2022 powinna zostać uchwalona?', 2, 'Sejm 10 kadencji, posiedzenie nr 16, głosowanie nr 19 – głosowanie nad całością projektu', 'https://api.sejm.gov.pl/sejm/term10/votings/16/19/pdf', '2024-07-24'),
  (109, 101, 9, 'Czy ustawa o zmianie ustawy o udzielaniu cudzoziemcom ochrony na terytorium Rzeczypospolitej Polskiej (zawieszenie prawa do azylu) powinna zostać uchwalona?', 2, 'Sejm 10 kadencji, posiedzenie nr 29, głosowanie nr 42 – głosowanie nad całością projektu', 'https://api.sejm.gov.pl/sejm/term10/votings/29/42/pdf', '2025-02-21'),
  (110, 101, 10, 'Czy ustawa o zmianie ustawy – Kodeks karny (mowa nienawiści) powinna zostać uchwalona?', 2, 'Sejm 10 kadencji, posiedzenie nr 30, głosowanie nr 16 – głosowanie nad całością projektu', 'https://api.sejm.gov.pl/sejm/term10/votings/30/16/pdf', '2025-03-06'),
  (111, 101, 11, 'Czy ustawa o zmianie ustawy o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych oraz niektórych innych ustaw (obniżenie składki zdrowotnej) powinna zostać uchwalona?', 2, 'Sejm 10 kadencji, posiedzenie nr 32, głosowanie nr 17 – głosowanie nad całością projektu', 'https://api.sejm.gov.pl/sejm/term10/votings/32/17/pdf', '2025-04-04'),
  (112, 101, 12, 'Czy ustawa o zmianie ustawy o inwestycjach w zakresie elektrowni wiatrowych oraz niektórych innych ustaw (ceny energii) powinna zostać uchwalona?', 2, 'Sejm 10 kadencji, posiedzenie nr 37, głosowanie nr 60 – głosowanie nad całością projektu', 'https://api.sejm.gov.pl/sejm/term10/votings/37/60/pdf', '2025-06-25'),
  (113, 101, 13, 'Czy ustawa o rynku kryptoaktywów powinna zostać uchwalona?', 2, 'Sejm 10 kadencji, posiedzenie nr 41, głosowanie nr 63 – głosowanie nad całością projektu', 'https://api.sejm.gov.pl/sejm/term10/votings/41/63/pdf', '2025-09-26'),
  (114, 101, 14, 'Czy ustawa o zmianie ustawy o Krajowej Radzie Sądownictwa oraz ustawy – Kodeks wyborczy (wybór sędziów do KRS) powinna zostać uchwalona?', 2, 'Sejm 10 kadencji, posiedzenie nr 50, głosowanie nr 104 – głosowanie nad całością projektu', 'https://api.sejm.gov.pl/sejm/term10/votings/50/104/pdf', '2026-01-23'),
