  (116, 101, 16, 'Czy ustawa o koordynacji działań antykorupcyjnych oraz o likwidacji Centralnego Biura Antykorupcyjnego powinna zostać uchwalona?', 2, 'Sejm 10 kadencji, posiedzenie nr 53, głosowanie nr 68 – głosowanie nad całością projektu', 'https://api.sejm.gov.pl/sejm/term10/votings/53/68/pdf', '2026-03-13'),
  (117, 101, 17, 'Czy ustawa o statusie osoby najbliższej w związku i umowie o wspólnym pożyciu powinna zostać uchwalona?', 2, 'Sejm 10 kadencji, posiedzenie nr 58, głosowanie nr 62 – głosowanie nad całością projektu', 'https://api.sejm.gov.pl/sejm/term10/votings/58/62/pdf', '2026-05-29'),
  (118, 101, 18, 'Czy senacki projekt ustawy o zmianie ustawy – Kodeks wyborczy oraz ustawy o referendum lokalnym powinien zostać uchwalony?', 2, 'Sejm 10 kadencji, posiedzenie nr 64, głosowanie nr 29 – głosowanie nad całością projektu', 'https://api.sejm.gov.pl/sejm/term10/votings/64/29/pdf', '2026-09-04'),
  (119, 101, 19, 'Czy ustawa o wykonywaniu orzeczeń Europejskiego Trybunału Praw Człowieka powinna zostać uchwalona?', 2, 'Sejm 10 kadencji, posiedzenie nr 64, głosowanie nr 33 – głosowanie nad całością projektu', 'https://api.sejm.gov.pl/sejm/term10/votings/64/33/pdf', '2026-09-04'),
  (120, 101, 20, 'Czy ustawa o przywróceniu prawa do niezależnego i bezstronnego sądu ustanowionego na podstawie prawa przez uregulowanie skutków uchwał Krajowej Rady Sądownictwa podjętych w latach 2018–2025 powinna zostać uchwalona?', 2, 'Sejm 10 kadencji, posiedzenie nr 67, głosowanie nr 201 – głosowanie nad całością projektu', 'https://api.sejm.gov.pl/sejm/term10/votings/67/201/pdf', '2026-10-22');
